const PALETTES={
 hills:{sky:['#83cfe9','#d7efdc'],layers:['#92baba','#83ad8e','#7ca26a'],soil:'#a47b49',edge:'#466c32',top:'#7fc444',shine:'#a0d65a'},
 mountains:{sky:['#96bed6','#e2e8e5'],layers:['#93a5b5','#7c909e','#647e86'],soil:'#827f72',edge:'#505d55',top:'#859774',shine:'#bac49a'},
 moon:{sky:['#111428','#343759'],layers:['#626481','#54566d','#464b60'],soil:'#777c88',edge:'#505665',top:'#b0b6bd',shine:'#d8d9dd'},
 highway:{sky:['#8acde7','#e3ead3'],layers:['#a3c2b5','#8ab08a','#749365'],soil:'#a08765',edge:'#3a4144',top:'#5d6668',shine:'#7c8381'},
 city:{sky:['#b3d6df','#f4dcc6'],layers:['#a6b5bd','#839ba8','#6f8c96'],soil:'#998774',edge:'#373e40',top:'#606b70',shine:'#7b8586'},
 winter:{sky:['#90b9d3','#e8f4fa'],layers:['#b5cbdc','#9cb6c8','#8da8b8'],soil:'#8a9fac',edge:'#98bccd',top:'#eef7fa',shine:'#fff'}
};
const BIOME_LENGTH=30000,BRIDGE_CHUNK=3200;
let worldSeed=1,biomeOrder=['hills','mountains','highway','city','winter'];
function hash(n,salt=0){let v=(Math.floor(n)^worldSeed^Math.imul(salt,0x9e3779b9))>>>0;v=Math.imul(v^(v>>>16),0x7feb352d);v=Math.imul(v^(v>>>15),0x846ca68b);return ((v^(v>>>16))>>>0)/4294967296}
function setWorldSeed(seed){worldSeed=seed>>>0;biomeOrder=['hills','mountains','highway','city','winter'];for(let j=4;j>0;j--){let k=Math.floor(hash(j,71)*(j+1));[biomeOrder[j],biomeOrder[k]]=[biomeOrder[k],biomeOrder[j]]}}
function newWorldSeed(){let seed=globalThis.crypto?.getRandomValues?globalThis.crypto.getRandomValues(new Uint32Array(1))[0]:Math.floor(Math.random()*4294967296);if(seed===worldSeed)seed=(seed+1)>>>0;setWorldSeed(seed)}
function biomeRegion(region){return biomeOrder[((region%5)+5)%5]}
function mapBiome(t,x){return t===6?biomeRegion(Math.max(0,Math.floor(x/BIOME_LENGTH))):MAPS[t].biome}
function ease(t){return t*t*(3-2*t)}
function smoothNoise(x,salt){const i=Math.floor(x),f=ease(x-i);return (hash(i,salt)*(1-f)+hash(i+1,salt)*f)*2-1}
function profile(b,x){const i=['hills','mountains','moon','highway','city','winter'].indexOf(b),amplitudes=[[65,26,8],[120,38,12],[76,32,12],[25,10,3],[34,12,4],[70,28,8]][i],wavelengths=[[230,115,65],[350,160,80],[300,145,85],[480,200,110],[410,185,95],[265,140,75]][i];let v=0;for(let j=0;j<3;j++){const phase=hash(i,j+19)*Math.PI*2,freq=.88+hash(i,j+31)*.25,amp=.9+hash(i,j+47)*.2;v+=amplitudes[j]*amp*Math.sin(x*freq/wavelengths[j]+phase)}return v+smoothNoise(x/520,i+91)*(b==='highway'?12:28)}
function rawTerrain(t,x){const ramp=ease(Math.min(1,Math.max(0,(x-800)/650)));let v=profile(mapBiome(t,x),x);if(t===6){const boundary=Math.round(x/BIOME_LENGTH)*BIOME_LENGTH;if(boundary>0&&Math.abs(x-boundary)<600){const region=boundary/BIOME_LENGTH,f=ease((x-boundary+600)/1200);v=profile(biomeRegion(region-1),x)*(1-f)+profile(biomeRegion(region),x)*f}}return ramp*v*(1+Math.min(.15,Math.max(0,x-3000)/80000))}
function bridgeForChunk(t,chunk){if(chunk<0||hash(chunk,t+111)>.72)return null;const a=chunk*BRIDGE_CHUNK+1050+hash(chunk,t+133)*1350;return [a,a+260+hash(chunk,t+151)*160]}
function bridgesInRange(t,left,right){const bridges=[];for(let j=Math.max(0,Math.floor(left/BRIDGE_CHUNK));j<=Math.floor(right/BRIDGE_CHUNK);j++){const bridge=bridgeForChunk(t,j);if(bridge&&bridge[1]>=left&&bridge[0]<=right)bridges.push(bridge)}return bridges}
function bridgeAt(t,x){const bridge=bridgeForChunk(t,Math.floor(x/BRIDGE_CHUNK));return bridge&&x>=bridge[0]&&x<=bridge[1]?bridge:null}
function biomeBoundaries(left,right){const boundaries=[];for(let x=(Math.floor(left/BIOME_LENGTH)+1)*BIOME_LENGTH;x<right;x+=BIOME_LENGTH)if(x>0)boundaries.push(x);return boundaries}
function mapTerrain(t,x){const bridge=bridgeAt(t,x);if(!bridge)return rawTerrain(t,x);const [a,b]=bridge,k=(x-a)/(b-a);return rawTerrain(t,a)*(1-k)+rawTerrain(t,b)*k}
function groundHeight(t,x){const bridge=bridgeAt(t,x);return bridge?mapTerrain(t,x)+Math.sin(Math.PI*(x-bridge[0])/(bridge[1]-bridge[0]))*180:rawTerrain(t,x)}
function mapBackground(t,x){const b=mapBiome(t,x),p=PALETTES[b],g=ctx.createLinearGradient(0,0,0,H);if(document.body)document.body.dataset.biome=b;g.addColorStop(0,p.sky[0]);g.addColorStop(1,p.sky[1]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);if(b==='moon'){for(let j=0;j<100;j++)circle((j*137.37)%W,(j*j*19.7)%(H*.65),j%5?1:2,'#fff9');circle(W*.82,118,43,'#6fb8ce');ctx.save();ctx.globalAlpha=.65;path([[W*.8,79],[W*.81,116],[W*.835,129],[W*.833,153],[W*.815,133],[W*.79,124]],'#66a785');ctx.restore()}else{circle(W*.82,120,42,b==='winter'?'#fffbe7':'#fff3b0');for(let j=0;j<8;j++){let cx=((j*270-cam*.12)%(W+270)+W+270)%(W+270)-80,cy=110+(j%3)*44;circle(cx,cy,25,'#ffffff90');circle(cx+28,cy-10,34,'#ffffff90');circle(cx+60,cy,25,'#ffffff90')}}
for(let l=0;l<3;l++){let pts=[[0,H]];for(let sx=0;sx<=W+24;sx+=24){let phase=sx+cam*(.08+l*.07),y=H*(.44+l*.1);if(b==='mountains'||b==='winter')y+=Math.abs(((phase/180)%2)-1)*120-75;else y+=Math.sin(phase/(250-l*40))*55+Math.sin(phase/117)*18;pts.push([sx,y])}pts.push([W,H]);path(pts,p.layers[l]);if(b==='mountains'||b==='winter'){for(let j=0;j<7;j++){const peak=((180+j*360-cam*(.08+l*.07))%2520+2520)%2520;path([[peak-23,H*(.44+l*.1)-42],[peak,H*(.44+l*.1)-75],[peak+24,H*(.44+l*.1)-42],[peak+8,H*(.44+l*.1)-48],[peak-4,H*(.44+l*.1)-39]],'#e8f2f1')}}}}
function pine(x,y,size,snow){ctx.save();ctx.translate(x,y);ctx.scale(size,size);ctx.fillStyle='#75664e';ctx.fillRect(-5,-90,10,90);for(let j=0;j<3;j++){const yy=-122+j*28,w=23+j*13;path([[0,yy],[-w,yy+52],[w,yy+52]],snow?'#4c7578':'#3d7357','#2e5950',1);if(snow)path([[0,yy],[-w*.7,yy+36],[-w*.1,yy+29],[w*.6,yy+34]],'#e6f3f6')}ctx.restore()}
function building(x,y,height,width){ctx.fillStyle='#465665';ctx.fillRect(x-width/2,y-height,width,height);ctx.fillStyle='#728895';ctx.fillRect(x-width/2+5,y-height+5,width-10,height-5);ctx.fillStyle='#344c58';ctx.fillRect(x-width/2-5,y-height-6,width+10,8);for(let row=0;row<Math.floor(height/26)-1;row++)for(let col=0;col<Math.floor(width/23)-1;col++){ctx.fillStyle=(row+col)%3?'#e9d3a3':'#b2d2d9';ctx.fillRect(x-width/2+12+col*23,y-height+16+row*26,11,13)}}
function mapScenery(t,left,right){for(let x=Math.floor(left/230)*230;x<right;x+=230){if(bridgeAt(t,x))continue;let b=mapBiome(t,x),y=terrain(x)-10;if(b==='hills')tree(x,y,1.55+.25*Math.sin(x/33));if(b==='mountains'||b==='winter')pine(x,y,1.1+.15*Math.sin(x/21),b==='winter');if(b==='city'){building(x,y,95+Math.abs(Math.sin(x))*110,68+Math.abs(Math.cos(x))*35);ctx.fillStyle='#3e565e';ctx.fillRect(x+70,y-100,4,100);circle(x+78,y-100,9,'#ffe5a5')}if(b==='highway'){ctx.fillStyle='#d3d7cf';ctx.fillRect(x,y-43,4,43);path([[x-18,y-60],[x+35,y-60],[x+35,y-35],[x-18,y-35]],'#447d63','#e1e8d7');ctx.fillStyle='#fff';ctx.font='bold 12px Arial';ctx.fillText('→',x+4,y-42)}if(b==='moon'){ctx.save();ctx.scale(1,.38);circle(x,y/.38-2,23,'#626874','#8b9199');ctx.restore()}}}
function drawGround(t,left,right,bottom){const bounds=[left,...(t===6?biomeBoundaries(left,right):[]),right];for(let j=0;j<bounds.length-1;j++){const a=bounds[j],b=bounds[j+1],p=PALETTES[mapBiome(t,(a+b)/2)],pts=[[a,bottom]];for(let x=a;x<b;x+=6)pts.push([x,groundHeight(t,x)]);pts.push([b,groundHeight(t,b)],[b,bottom]);path(pts,p.soil)}
for(let x=Math.floor(left/38)*38;x<right;x+=38){let b=mapBiome(t,x),y=groundHeight(t,x);for(let j=0;j<7;j++){ctx.fillStyle=b==='moon'?'#5f6572':b==='winter'?'#afc0ca':j%2?'#bf925b':'#706e5940';ctx.fillRect(x+Math.sin(x+j*8)*12,y+25+j*27,5+j%3,3)}}
for(let j=0;j<bounds.length-1;j++){const a=bounds[j],b=bounds[j+1],p=PALETTES[mapBiome(t,(a+b)/2)];ctx.beginPath();ctx.moveTo(a,groundHeight(t,a));for(let x=a+5;x<b;x+=5)ctx.lineTo(x,groundHeight(t,x));ctx.lineTo(b,groundHeight(t,b));ctx.lineWidth=14;ctx.strokeStyle=p.edge;ctx.stroke();ctx.lineWidth=9;ctx.strokeStyle=p.top;ctx.stroke();ctx.lineWidth=3;ctx.strokeStyle=p.shine;ctx.stroke()}
for(let x=Math.floor(left/65)*65;x<right;x+=65){if(['city','highway'].includes(mapBiome(t,x))&&!bridgeAt(t,x)){ctx.beginPath();ctx.moveTo(x,terrain(x)-2);ctx.lineTo(x+26,terrain(x+26)-2);ctx.lineWidth=3;ctx.strokeStyle='#f5e4a9';ctx.stroke()}}
for(const [a,b] of bridgesInRange(t,left,right)){const urban=['city','highway'].includes(mapBiome(t,a)),deck=urban?'#747d82':'#9e7143';ctx.strokeStyle=urban?'#93a2ad':'#a88253';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(a,terrain(a));ctx.lineTo(b,terrain(b));ctx.stroke();for(let x=a+15;x<b;x+=24){const y=terrain(x);ctx.strokeStyle='#544936';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y-5);ctx.lineTo(x,y+7);ctx.stroke();ctx.strokeStyle=deck;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x,y-7);ctx.lineTo(x,y-40);ctx.stroke();if((x-a-15)%72===0){ctx.strokeStyle=urban?'#6f7d88':'#785539';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(x,y+8);ctx.lineTo(x,groundHeight(t,x)+20);ctx.stroke()}}ctx.strokeStyle=deck;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(a,terrain(a)-40);ctx.lineTo(b,terrain(b)-40);ctx.stroke();ctx.strokeStyle=mapBiome(t,a)==='moon'?'#444956':'#7baec9';ctx.lineWidth=14;ctx.beginPath();ctx.moveTo(a+60,Math.max(terrain(a),terrain(b))+150);ctx.lineTo(b-60,Math.max(terrain(a),terrain(b))+150);ctx.stroke()}}
function snowing(){return time>=snowStart&&time<snowEnd}
function drawWeather(){const center=cam+W/scale()*.5;if(mapBiome(track,center)!=='winter'||!snowing())return;ctx.fillStyle='#d7e4ef18';ctx.fillRect(0,0,W,H);for(let j=0;j<150;j++){const x=((j*137.1+time*(18+j%7)*1.8+Math.sin(time+j)*20)%W+W)%W,y=(j*53+time*(55+j%35))%H;circle(x,y,1+j%3*.5,'#ffffffcf')}}


